oxy_webhelp_navlinks = {"aws_storage_tiering_setup-d39536e17493":{"topics":[{"title":"Evaluate AWS storage tiering options","shortdesc":"<p class=\"shortdesc\">Before setting up AWS storage tiering, it is important to evaluate the tiering         options to align with archiving needs, balancing cost, performance, and data retrieval. Key         considerations include Amazon S3 storage classes, instant tiering, and encryption         standards.<\/p>","href":"saas\/aws_storage_tiering_evaluate_options.html","attributes":{"data-id":"aws_storage_tiering_evaluate_options"},"menu":{"hasChildren":false},"tocID":"aws_storage_tiering_evaluate_options-d39536e17507","next":"aws_storage_tiering_evaluate_options-d39536e17507"},{"title":"Required permissions for AWS storage tiering","shortdesc":"<p class=\"shortdesc\">To set up AWS storage tiering, it is required to assign specific permissions to the             <span class=\"ph\">RSC<\/span> user.<\/p>","href":"saas\/required_permissions_storage_tiering.html","attributes":{"data-id":"required_permissions_storage_tiering"},"menu":{"hasChildren":false},"tocID":"required_permissions_storage_tiering-d39536e17586","topics":[]},{"title":"Quotas prerequisites for Amazon RDS archiving","shortdesc":"<p class=\"shortdesc\">Information about the Amazon RDS instance quotas prerequisites for archiving Amazon         RDS PostgreSQL, Aurora PostgreSQL, RDS MySQL, Aurora MySQL, and RDS SQL Server databases.<\/p>","href":"saas\/aws_rds_quota_prereq_archiving.html","attributes":{"data-id":"aws_rds_quota_prereq_archiving"},"menu":{"hasChildren":false},"tocID":"aws_rds_quota_prereq_archiving-d39536e17600","topics":[]},{"title":"Prerequisites for archiving Amazon RDS using Exocompute","shortdesc":"<p class=\"shortdesc\">When archiving Amazon RDS databases using a central Exocompute configuration, certain         resources must exist in the Exocompute account before archiving can succeed.<\/p>","href":"aws\/aws_rds_archiving_prereq_exo.html","attributes":{"data-id":"aws_rds_archiving_prereq_exo"},"menu":{"hasChildren":false},"tocID":"aws_rds_archiving_prereq_exo-d39536e17611","topics":[]},{"title":"Amazon RDS archival cost and resource lifecycle","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> creates temporary AWS resources each time <span class=\"ph\">RSC<\/span>         archives an Amazon RDS database. Understanding what is created, when it is removed, and what         drives cost helps plan and monitor archival spend.<\/p>","href":"aws\/aws_rds_archival_resource_lifecycle.html","attributes":{"data-id":"aws_rds_archival_resource_lifecycle"},"menu":{"hasChildren":false},"tocID":"aws_rds_archival_resource_lifecycle-d39536e17622","topics":[]},{"title":"Configure AWS storage tiering","shortdesc":"<p class=\"shortdesc\">To configure AWS storage tiering, you must create an archival location for archiving         snapshots and storing backups.<\/p>","href":"saas\/aws_config_storage_tiering.html","attributes":{"data-id":"aws_config_storage_tiering"},"menu":{"hasChildren":false},"tocID":"aws_config_storage_tiering-d39536e17638","next":"aws_config_storage_tiering-d39536e17638"}]}};